import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/strengthen/commands.md","filePath":"modules/strengthen/commands.md","lastUpdated":0}`),a={name:`modules/strengthen/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>强化模块的命令与权限: 每条命令做什么, 需要哪个权限, 出问题时先敲哪一条</p><p>EmakiStrengthen 的主命令是 <code>/emakistrengthen</code>, 别名 <code>/estrengthen</code>. 你用它打开强化 GUI; 管理员还用它检查主手装备, 刷新展示, 设置星级, 清理状态和发放强化材料</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/estrengthen help</code></td><td>显示帮助</td><td>基础</td></tr><tr><td><code>/estrengthen open</code></td><td>打开强化 GUI</td><td><code>emakistrengthen.use</code></td></tr><tr><td><code>/estrengthen affix [recipe]</code></td><td>打开词条强化 GUI, 只有玩家能执行; 不填 <code>recipe</code> 时按当前物品匹配</td><td><code>use</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen branch [id]</code></td><td>给主手物品选择分支, 只有玩家能执行; 不填 <code>id</code> 时列出当前可选的分支 ID</td><td><code>use</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen reload</code></td><td>重载配置, GUI, 语言和配方</td><td><code>reload</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen inspect [player]</code></td><td>检查指定玩家或自己的主手物品</td><td><code>use</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen refresh [player]</code></td><td>刷新指定玩家或自己的物品展示</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen setstar &lt;star&gt; [recipe]</code></td><td>设置执行者主手物品的星级; 这条命令没有 player 参数</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen convert-legacy [confirm]</code></td><td>把 <code>recipes/*.yml</code> 里已废弃的 <code>match</code> 块转换成 <code>matcher</code> 加顶层字段. 不带参数只做预演; 加 <code>confirm</code> (或 <code>--apply</code>) 才实际改写, 并留一份 <code>.bak</code> 备份. 详见<a href="./recipes.html#从-match-迁移">强化配方</a></td><td><code>admin</code></td></tr><tr><td><code>/estrengthen clearstate</code></td><td>清除执行者主手的强化层, 只有玩家能执行</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen clearcrack</code></td><td>清除执行者主手的锻印值, 只有玩家能执行</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen givecatalyst &lt;material&gt; [amount] [player]</code></td><td>发放强化材料</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen operation [list|&lt;operationId&gt;]</code></td><td>列出已经注册的强化操作, 或者查看单个 <code>operationId</code> 的详情. 不填参数等同于 <code>list</code></td><td><code>admin</code></td></tr><tr><td><code>/estrengthen pity [list|diagnose|set|clear] ...</code></td><td>管理保底 (连续失败到一定次数后必定成功) 计数器. <code>list [group]</code> 用来查看, <code>diagnose</code> 输出存储状态, <code>set &lt;scope&gt; &lt;group&gt; &lt;owner&gt; &lt;counter&gt;</code> (<code>scope</code> 填 <code>player</code> 或 <code>item</code>) 写入计数, <code>clear &lt;group&gt;</code> 清空一个分组. 不填参数等同于 <code>list</code></td><td><code>admin</code></td></tr><tr><td><code>/estrengthen debug &lt;status|player|module|all&gt; [...]</code></td><td>查看或切换调试输出</td><td><code>debug</code> 或 <code>admin</code></td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakistrengthen.use</code></td><td>true</td><td>使用基础强化功能</td></tr><tr><td><code>emakistrengthen.reload</code></td><td>op</td><td>重载配置</td></tr><tr><td><code>emakistrengthen.debug</code></td><td>op</td><td>调试命令</td></tr><tr><td><code>emakistrengthen.admin</code></td><td>op</td><td>管理员功能</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要强化装备</td><td><code>/estrengthen open</code></td><td>打开强化 GUI</td></tr><tr><td>修改了配方, GUI 或语言</td><td><code>/estrengthen reload</code></td><td>重载运行配置</td></tr><tr><td>装备强化状态不对</td><td><code>/estrengthen inspect</code></td><td>查看主手物品的强化层和匹配配方</td></tr><tr><td>展示没有刷新</td><td><code>/estrengthen refresh &lt;player&gt;</code></td><td>重建玩家物品展示</td></tr><tr><td>测试某个星级效果</td><td><code>/estrengthen setstar &lt;star&gt; [recipe]</code></td><td>直接设置执行者主手物品星级</td></tr><tr><td>调试异常状态</td><td><code>/estrengthen debug ...</code></td><td>查看模块, 玩家或全局调试信息</td></tr></tbody></table><h2 id="管理建议" tabindex="-1">管理建议 <a class="header-anchor" href="#管理建议" aria-label="Permalink to “管理建议”">​</a></h2><ul><li><code>setstar</code>, <code>clearstate</code>, <code>clearcrack</code> 操作的都是执行者手里的主手物品, 执行前先确认手里拿的是测试装备</li><li><code>refresh</code> 只负责把展示刷出来, 不会替你修正配错的配方</li><li>改完配方先 reload, 再用测试装备分别验证成功, 失败, 保护材料, 星级写入和属性写入</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};